using Microsoft.Extensions.Logging;

namespace MyMauiApp;

public static class MauiProgram
{
    public static MauiApp CreateMauiApp()
    {
        var builder = MauiApp.CreateBuilder();
        builder
            .UseMauiApp<App>()
            .ConfigureFonts(fonts =>
            {
                fonts.AddFont("OpenSans-Regular.ttf", "OpenSansRegular");
            });

        // --- Services ---
        // Singleton: one HttpClient and one DataService instance for the entire app.
        // REST clients are expensive to create and should be reused to benefit from
        // connection pooling and avoid socket exhaustion.
        builder.Services.AddSingleton<HttpClient>();
        builder.Services.AddSingleton<IDataService, DataService>();

        // --- ViewModels ---
        // Transient: a fresh ViewModel per request so each page gets its own state.
        // This avoids stale data when navigating back and forth.
        builder.Services.AddTransient<MainViewModel>();
        builder.Services.AddTransient<DetailViewModel>();

        // --- Pages ---
        // Transient: a new page instance each navigation, matching the transient
        // ViewModels. Shell/NavigationPage will manage the page lifecycle.
        builder.Services.AddTransient<MainPage>();
        builder.Services.AddTransient<DetailPage>();

#if DEBUG
        builder.Logging.AddDebug();
#endif

        return builder.Build();
    }
}

